import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { productsAPI } from '../services/api';

const Home = ({ addToCart, showNotification }) => {
  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedCategory, setSelectedCategory] = useState('');
  const [categories, setCategories] = useState([]);
  const [likedProducts, setLikedProducts] = useState(new Set());

  useEffect(() => {
    fetchProducts();
  }, [searchTerm, selectedCategory]);

  const fetchProducts = async () => {
    try {
      const params = {};
      if (searchTerm) params.search = searchTerm;
      if (selectedCategory) params.category = selectedCategory;

      const response = await productsAPI.getAll(params);
      setProducts(response.data);

      // Extract unique categories
      const uniqueCategories = [...new Set(response.data.map(p => p.category))];
      setCategories(uniqueCategories);
    } catch (error) {
      console.error('Error fetching products:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleLike = async (productId) => {
    const token = localStorage.getItem('token');
    if (!token) {
      showNotification('Please login to like products', 'info');
      return;
    }

    try {
      const response = await productsAPI.like(productId);
      if (response.data.liked) {
        setLikedProducts(prev => new Set([...prev, productId]));
      } else {
        setLikedProducts(prev => {
          const newSet = new Set(prev);
          newSet.delete(productId);
          return newSet;
        });
      }
      // Update the product in the list
      setProducts(prev => prev.map(p => 
        p._id === productId 
          ? { ...p, likes: response.data.liked 
              ? [...(p.likes || []), 'current-user'] 
              : (p.likes || []).filter(id => id !== 'current-user') }
          : p
      ));
    } catch (error) {
      console.error('Error liking product:', error);
      showNotification('Error liking product. Please try again.', 'error');
    }
  };

  const handleBuyNow = async (product) => {
    const token = localStorage.getItem('token');
    if (!token) {
      showNotification('Please login to buy products', 'info');
      return;
    }

    const address = prompt('Enter shipping address:');
    const phone = prompt('Enter phone number:');

    if (address && phone) {
      try {
        await productsAPI.buyNow(product._id, {
          quantity: 1,
          shippingAddress: address,
          phoneNumber: phone
        });
        showNotification('Order placed successfully!', 'success');
        fetchProducts(); // Refresh to update stock
      } catch (error) {
        showNotification('Error placing order: ' + (error.response?.data?.message || 'Unknown error'), 'error');
      }
    }
  };

  if (loading) return <div className="loading">Loading products...</div>;

  return (
    <div className="container">
      <div style={{ marginBottom: '2rem' }}>
        <h2>Featured Products</h2>

        {/* Search and Filter */}
        <div style={{ display: 'flex', gap: '1rem', marginTop: '1rem', flexWrap: 'wrap' }}>
          <input
            type="text"
            placeholder="Search products..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            style={{ padding: '0.5rem', borderRadius: '5px', border: '1px solid #ddd', flex: 1, minWidth: '200px' }}
          />
          <select
            value={selectedCategory}
            onChange={(e) => setSelectedCategory(e.target.value)}
            style={{ padding: '0.5rem', borderRadius: '5px', border: '1px solid #ddd' }}
          >
            <option value="">All Categories</option>
            {categories.map(category => (
              <option key={category} value={category}>{category}</option>
            ))}
          </select>
        </div>
      </div>

      <div className="products-grid">
        {products.map(product => (
          <div key={product._id} className="product-card">
            <img 
              src={product.image || 'https://via.placeholder.com/300x200'} 
              alt={product.name} 
            />
            <h3>{product.name}</h3>
            <p className="price">₹{product.price}</p>
            <p>{product.description.substring(0, 100)}...</p>
            <p><strong>Stock:</strong> {product.stock}</p>
            <p><strong>Likes:</strong> {product.likes?.length || 0}</p>

            <div style={{ display: 'flex', flexWrap: 'wrap', gap: '0.5rem', justifyContent: 'center' }}>
              <Link to={`/product/${product._id}`} className="btn">
                View Details
              </Link>
              <button 
                onClick={() => addToCart(product)} 
                className="btn"
                disabled={product.stock === 0}
              >
                Add to Cart
              </button>
              <button 
                onClick={() => handleBuyNow(product)} 
                className="btn btn-success"
                disabled={product.stock === 0}
              >
                Buy Now
              </button>
              <button 
                onClick={() => handleLike(product._id)} 
                className={`btn ${likedProducts.has(product._id) ? 'btn-danger' : 'btn-secondary'}`}
              >
                {likedProducts.has(product._id) ? '❤️' : '🤍'}
              </button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default Home;
